const express = require('express');
const { Server } = require('@tus/server');
const { FileStore } = require('@tus/file-store');
const { verifyBearerToken } = require('../auth');

const router = express.Router();
const tus = new Server({
  path: '/resumable/chunks',
  datastore: new FileStore({ directory: './data/chunks' })
});

router.patch('/resumable/chunks/:id', verifyBearerToken, async (req, res) => {
  const upload = await tus.datastore.getUpload(req.params.id);
  if (!upload) return res.status(404).end();

  if (upload.metadata?.ownerId !== req.user.id) {
    return res.status(403).json({ error: 'Forbidden: you are not authorized to upload chunks to this file' });
  }

  tus.handle(req, res);
});
